import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';

const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const sha = file => hash(fs.readFileSync(file));
const read = file => JSON.parse(fs.readFileSync(file, 'utf8'));
const root = path.resolve('target/course-presentation/incremental-native');
const progressFile = 'target/course-presentation/incremental-batches/23639a9ee49402a71f10/progress.json';
const output = path.resolve('target/course-presentation/native-dll-storage');
const owned = file => {
  const absolute = path.resolve(file);
  assert(absolute.startsWith(root + path.sep));
  assert(['dxcompiler.dll', 'dxil.dll'].includes(path.basename(absolute)));
  assert.equal(path.basename(path.dirname(absolute)), 'bin');
  assert(!fs.lstatSync(absolute).isSymbolicLink());
  return absolute;
};
const [mode, input, expected, limit] = process.argv.slice(2);
fs.mkdirSync(output, {recursive: true});
if (mode === 'audit') {
  const progress = read(progressFile), groups = new Map(), files = [];
  for (const item of Object.values(progress.items)) {
    if (!item.image || !item.sourceRecord || !['CAPTURED_AWAITING_ROOT_VISUAL_REVIEW', 'PUBLISHED_ROOT_REVIEWED'].includes(item.status)) continue;
    const record = read(item.sourceRecord);
    if (!record.runtimeDlls || !record.folder.startsWith(root + path.sep)) continue;
    for (const dll of Object.values(record.runtimeDlls)) {
      const file = owned(dll.path), stat = fs.statSync(file, {bigint: true});
      assert.equal(sha(file), dll.sha256);
      const key = dll.sha256 + ':' + stat.size;
      let group = groups.get(key);
      if (!group || group.count === 256) {
        group = {anchor: file, count: 0}; groups.set(key, group);
      }
      group.count++;
      files.push({file, anchor: group.anchor, sha256: dll.sha256, size: Number(stat.size), inode: String(stat.ino), links: Number(stat.nlink)});
    }
  }
  const plan = {status: 'AUDIT_ONLY_NO_STORAGE_CHANGES', date: new Date().toISOString(), scope: 'Completed native evidence DLLs only; every original path and byte must remain. No executable, source, PNG, active workbench or compiler cache is changed.', files};
  const bytes = JSON.stringify(plan, null, 2) + '\n', file = path.join(output, 'audit-' + hash(bytes).slice(0, 20) + '.json');
  fs.writeFileSync(file, bytes, {flag: 'wx'});
  console.log(JSON.stringify({file, sha256: sha(file), files: files.length, upperBoundSavedGiB: files.filter(row => row.file !== row.anchor).reduce((n, row) => n + row.size, 0) / 2 ** 30}));
} else {
  assert.equal(mode, 'apply'); assert.equal(sha(input), expected);
  const plan = read(input), count = Number(limit);
  assert(Number.isSafeInteger(count) && count > 0);
  const receiptFile = path.join(output, 'application-' + Date.now() + '.jsonl');
  fs.writeFileSync(receiptFile, '', {flag: 'wx'});
  let saved = 0, changed = 0;
  for (const row of plan.files) {
    if (row.file === row.anchor || changed === count) continue;
    const file = owned(row.file), anchor = owned(row.anchor);
    assert.equal(sha(file), row.sha256); assert.equal(sha(anchor), row.sha256);
    const before = fs.statSync(file, {bigint: true}), source = fs.statSync(anchor, {bigint: true});
    if (before.ino === source.ino && before.dev === source.dev) continue;
    assert.equal(before.size, BigInt(row.size)); assert.equal(before.dev, source.dev); assert(source.nlink < 900n);
    const temporary = path.join(path.dirname(file), '.storage-link-' + process.pid + '-' + changed + '.tmp');
    assert(!fs.existsSync(temporary));
    fs.linkSync(anchor, temporary);
    try { fs.renameSync(temporary, file); }
    catch (error) { if (fs.existsSync(temporary)) fs.unlinkSync(temporary); throw error; }
    const after = fs.statSync(file, {bigint: true});
    assert.equal(sha(file), row.sha256); assert.equal(after.ino, source.ino); assert.equal(after.dev, source.dev);
    const event = {file, anchor, sha256: row.sha256, bytes: row.size, beforeInode: String(before.ino), afterInode: String(after.ino), linkCount: Number(after.nlink), pathAndBytesPreserved: true};
    fs.appendFileSync(receiptFile, JSON.stringify(event) + '\n');
    if (before.nlink === 1n) saved += row.size;
    changed++;
  }
  console.log(JSON.stringify({receiptFile, receiptSha256: sha(receiptFile), changed, physicalBytesReleased: saved, scope: plan.scope}));
}
